// Create one Daytona sandbox, use its filesystem, then delete it.
package main

import (
	"context"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"time"

	"github.com/joho/godotenv"
	"github.com/sandbox-kit/kit/sdks/go/providers/daytona"
	"github.com/sandbox-kit/kit/sdks/go/sandbox"
)

func main() {
	if err := run(); err != nil {
		log.Fatal(err)
	}
}

func run() error {
	if err := godotenv.Load(".env"); err != nil {
		return fmt.Errorf("copy .env.example to .env and fill in its values: %w", err)
	}
	config := &sandbox.Config{
		Auth: &sandbox.AuthConfig{
			Credentials: &sandbox.APIKey{
				ApiKey: &sandbox.APIKeyCredentials{
					Key: os.Getenv("DAYTONA_API_KEY"),
				},
			},
		},
		Timeout: sandbox.Duration(2 * time.Minute),
	}
	if endpoint := os.Getenv("DAYTONA_API_URL"); endpoint != "" {
		config.Endpoint = sandbox.Value(endpoint)
	}
	if target := os.Getenv("DAYTONA_TARGET"); target != "" {
		config.Region = sandbox.Value(target)
	}
	client, err := sandbox.NewClient(daytona.New(), config)
	if err != nil {
		return err
	}
	defer client.Close(context.Background())

	ctx := context.Background()
	instance, err := client.Create(ctx, nil)
	if err != nil {
		return err
	}
	defer func() {
		if err := instance.Delete(context.Background(), &sandbox.DeleteOptions{Wait: sandbox.Value(true)}); err != nil {
			log.Printf("delete sandbox: %v", err)
		}
	}()
	return useFiles(ctx, instance)
}

func useFiles(ctx context.Context, instance *sandbox.Sandbox) error {
	localDir, err := os.MkdirTemp("", "sandbox-kit-files-")
	if err != nil {
		return err
	}
	defer os.RemoveAll(localDir)

	files := instance.Filesystem()
	const remoteDir = "/tmp/kit-files"
	const remote = remoteDir + "/note.txt"
	body := []byte("hello from sandbox-kit\n")
	if err := files.MakeDirectory(ctx, remoteDir, nil); err != nil {
		return err
	}
	if err := files.WriteFile(ctx, remote, body, nil); err != nil {
		return err
	}
	data, err := files.ReadFile(ctx, remote, nil)
	if err != nil {
		return err
	}
	info, err := files.Stat(ctx, remote, nil)
	if err != nil {
		return err
	}
	entries, err := files.ListDirectory(ctx, remoteDir, nil)
	if err != nil {
		return err
	}
	local := filepath.Join(localDir, "note.txt")
	if err := files.CopyToLocal(ctx, remote, local, nil); err != nil {
		return err
	}
	copied, err := os.ReadFile(local)
	if err != nil {
		return err
	}
	if string(copied) != string(data) {
		return fmt.Errorf("local copy %q does not match remote %q", copied, data)
	}
	remoteCopy := remoteDir + "/copy.txt"
	if err := files.CopyFromLocal(ctx, local, remoteCopy, nil); err != nil {
		return err
	}
	if err := files.Remove(ctx, remoteCopy, nil); err != nil {
		return err
	}
	if err := files.Remove(ctx, remoteDir, &sandbox.RemoveOptions{Recursive: sandbox.Value(true)}); err != nil {
		return err
	}
	fmt.Printf("Daytona files ok: %s (%d bytes, %d entries)\n", instance.ID(), info.GetSize(), len(entries))
	return nil
}

