  const remoteDir = "/tmp/kit-files";
  const remote = `${remoteDir}/note.txt`;
  const body = new TextEncoder().encode("hello from sandbox-kit\n");
  await sandbox.filesystem.makeDirectory(remoteDir);
  await sandbox.filesystem.writeFile(remote, body);
  const data = await sandbox.filesystem.readFile(remote);
  const info = await sandbox.filesystem.stat(remote);
  const entries = await sandbox.filesystem.listDirectory(remoteDir);
  const local = join(localDir, "note.txt");
  await sandbox.filesystem.copyToLocal(remote, local);
  const copied = await readFile(local);
  if (Buffer.compare(copied, Buffer.from(data)) !== 0) {
    throw new Error("local copy does not match the remote file");
