  await sandbox.filesystem.copyFromLocal(local, remoteCopy);
  await sandbox.filesystem.remove(remoteCopy);
  await sandbox.filesystem.remove(remoteDir, { recursive: true });
  console.log(
    `Daytona files ok: ${sandbox.id} (${info.size} bytes, ${entries.length} entries)`,
  );
} finally {
  await rm(localDir, { recursive: true, force: true });
  await sandbox.delete({ wait: true });
}

